import struct
import collections
import re
from base64 import b64decode

def analyze_file(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    # 1. Find common patterns (3-5 bytes)
    patterns = {}
    for size in range(3, 6):
        for i in range(len(data) - size):
            pattern = data[i:i+size]
            if pattern in patterns:
                patterns[pattern] += 1
            else:
                patterns[pattern] = 1

    print("Most common patterns:")
    for pattern, count in sorted(patterns.items(), key=lambda x: x[1], reverse=True)[:10]:
        print(f"Pattern: {pattern.hex()} ({pattern}) Count: {count}")

    # 2. Look for delimiters and segment lengths
    chunks = []
    current_chunk = b''
    for byte in data:
        if byte in [0x00, 0x0a, 0x20, 0x2c]:  # common delimiters
            if current_chunk:
                chunks.append(current_chunk)
            current_chunk = b''
        else:
            current_chunk += bytes([byte])

    chunk_lengths = collections.Counter([len(c) for c in chunks])
    print("\nMost common chunk lengths:")
    print(chunk_lengths.most_common(5))

    # 3. Try to interpret as floating point numbers
    floats = []
    for i in range(0, len(data)-3, 4):
        try:
            value = struct.unpack('f', data[i:i+4])[0]
            if -1000 < value < 1000:  # reasonable range
                floats.append(value)
        except:
            continue

    print("\nSample of potential float values:")
    print(floats[:10])

    # 4. Check for base64-like patterns
    b64_chars = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=")
    b64_segments = []
    current = ""
    for byte in data:
        char = chr(byte) if 32 <= byte <= 126 else '.'
        if char in b64_chars:
            current += char
        else:
            if len(current) >= 4:
                b64_segments.append(current)
            current = ""

    print("\nPotential base64 segments:")
    for seg in b64_segments[:5]:
        print(seg)

