def is_printable(s):
    return all(c in string.printable for c in s)

def try_float32_decode(data, offset=0):
    results = []
    multipliers = [1, 32, 64, 127, 255]

    for i in range(0, len(data)-3, 4):
        chunk = data[i:i+4]
        try:
            # Try both little and big endian
            float_val_le = struct.unpack('<f', chunk)[0]
            float_val_be = struct.unpack('>f', chunk)[0]

            for mult in multipliers:
                # Try little endian
                try:
                    char_le = chr(int(abs(float_val_le * mult)))
                    if char_le in string.printable:
                        results.append((offset+i, char_le, 'float32_le', mult))
                except (ValueError, OverflowError):
                    pass

                # Try big endian
                try:
                    char_be = chr(int(abs(float_val_be * mult)))
                    if char_be in string.printable:
                        results.append((offset+i, char_be, 'float32_be', mult))
                except (ValueError, OverflowError):
                    pass
        except struct.error:
            continue
    return results

def try_float64_decode(data, offset=0):
    results = []
    multipliers = [1, 32, 64, 127, 255]

    for i in range(0, len(data)-7, 8):
        chunk = data[i:i+8]
        try:
            # Try both little and big endian
            float_val_le = struct.unpack('<d', chunk)[0]
            float_val_be = struct.unpack('>d', chunk)[0]

            for mult in multipliers:
                # Try little endian
